CREATE TABLE IF NOT EXISTS usuaria(id BIGINT PRIMARY KEY, nome VARCHAR(120), nascimento DATE, perfil VARCHAR(30));
CREATE TABLE IF NOT EXISTS sinal_diario(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuaria_id BIGINT REFERENCES usuaria(id), data DATE NOT NULL, sono_min INT, fc_repouso INT, temp_delta DOUBLE, passos INT, UNIQUE(usuaria_id,data));
CREATE TABLE IF NOT EXISTS menstruacao(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuaria_id BIGINT REFERENCES usuaria(id), inicio DATE NOT NULL, fim DATE NOT NULL, fluxo VARCHAR(20), UNIQUE(usuaria_id,inicio));
CREATE TABLE IF NOT EXISTS sintoma(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuaria_id BIGINT REFERENCES usuaria(id), data DATE NOT NULL, tipo VARCHAR(30), intensidade INT CHECK(intensidade BETWEEN 0 AND 10));
CREATE TABLE IF NOT EXISTS compromisso(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuaria_id BIGINT REFERENCES usuaria(id), tipo VARCHAR(30), data TIMESTAMP, descricao VARCHAR(200), status VARCHAR(20));
